package com.daniil.wristlens.phone;
import android.content.*;import org.json.*;import com.daniil.wristlens.shared.Wire;import java.io.IOException;import java.util.*;
final class Tickets {
 @android.annotation.SuppressLint("ApplySharedPref") static synchronized String issue(Context c,String kind,String node,String value)throws Exception{SharedPreferences p=c.getSharedPreferences("tickets",0);SharedPreferences.Editor edit=p.edit();long now=System.currentTimeMillis();int live=0;for(var e:p.getAll().entrySet())try{if(new JSONObject(e.getValue().toString()).optLong("expires")<now)edit.remove(e.getKey());else live++;}catch(Exception x){edit.remove(e.getKey());}if(live>=64)throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_079));String token=UUID.randomUUID().toString();edit.putString(token,Wire.object("kind",kind,"node",node,"value",value,"expires",now+300000).toString());if(!edit.commit())throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_080));return token;}
 @android.annotation.SuppressLint("ApplySharedPref") static synchronized JSONObject consume(Context c,String token,String kind,String node)throws Exception{SharedPreferences p=c.getSharedPreferences("tickets",0);String value=p.getString(token,"");if(!p.edit().remove(token).commit())throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_081));JSONObject j=new JSONObject(value);if(!kind.equals(j.optString("kind"))||(!node.isEmpty()&&!node.equals(j.optString("node")))||j.optLong("expires")<System.currentTimeMillis())throw new IOException(com.daniil.wristlens.shared.Strings.tr(com.daniil.wristlens.shared.R.string.wl_082));return j;}
}
